  short nAuraStat;
  D2SkillsTxt *pSkillsTxt;

  nStateIdx = 0;
  if (0 < (short)D2Common::ITEMS::Items::sgptDataTable->nAllStatesDataTblFlag0x04Size) {
    do {
      eState = D2Common::DATATBLS::ItemStats::UNIT_GetUnitState
                         (pUnit,(int)D2Common::ITEMS::Items::sgptDataTable->
                                     pAllStatesDataTblFlag0x04[nStateIdx].nStateId);
      if ((((((eState != 0) &&
             (pStatList = D2Common::Stats::StatsEx::GetStatsByState
                                    (pUnit,(int)D2Common::ITEMS::Items::sgptDataTable->
                                                pAllStatesDataTblFlag0x04[nStateIdx].nStateId),
             pStatList != (D2StatListExStrc *)0x0)) &&
            (eSkill = D2Common::Stats::StatsEx::STATLIST_GetBaseStatValue
                                (pStatList,UNITSTAT_modifierlist_skill,0), 0 < (int)eSkill)) &&
           (((int)eSkill < D2Common::ITEMS::Items::sgptDataTable->nTxtSkillsCount &&
            (pSkillsTxt = D2Common::ITEMS::Items::sgptDataTable->pTxtSkills,
            pSkillsTxt + eSkill != (D2SkillsTxt *)0x0)))) &&
          ((nSkillLevel = D2Common::Stats::StatsEx::STATLIST_GetBaseStatValue
                                    (pStatList,UNITSTAT_modifierlist_level,0), 0 < nSkillLevel &&
           ((nAuraStat = pSkillsTxt[eSkill].aurastat[0], -1 < nAuraStat &&
            ((int)nAuraStat < D2Common::ITEMS::Items::sgptDataTable->nTxtItemStatCostSize)))))) &&
         (nAuraStatValue =
               D2Common::Stats::StatsEx::STATLIST_GetBaseStatValue(pStatList,(int)nAuraStat,0),
         0 < nAuraStatValue)) {
        pSkillDesc = D2Common::Skills::Skills::GetSkillDescription(eSkill);
        if (pSkillDesc == (D2SkillDescTxt *)0x0) {
          nCalcMin = D2Common::Skills::Skills::SERVER_MinDamage(pUnit,eSkill,nSkillLevel,1);
          *pnMinDmgAcc = *pnMinDmgAcc + (nCalcMin >> 8);
          nCalcMin = D2Common::Skills::Skills::SERVER_MaxDamage(pUnit,eSkill,nSkillLevel,1);
          *pnMaxDmgAcc = *pnMaxDmgAcc + (nCalcMin >> 8);
        }
        else {
          if (nAuraStatValue < 2) {
            nAuraStatValue = 1;
          }
          else if (2 < nAuraStatValue) {
            nAuraStatValue = 3;
          }
          nCalcResult = D2Common::Skills::Skills::SKILLS_EvalDescCalcBytecode
                                  (pUnit,*(uint32_t *)(pSkillDesc->dmelem + nAuraStatValue * 4),
                                   eSkill,nSkillLevel);
          *pnMinDmgAcc = *pnMinDmgAcc + nCalcResult;
          nCalcResult = D2Common::Skills::Skills::SKILLS_EvalDescCalcBytecode
                                  (pUnit,pSkillDesc->dmmin[nAuraStatValue + 2],eSkill,nSkillLevel);
          *pnMaxDmgAcc = *pnMaxDmgAcc + nCalcResult;
          byElemType = pSkillDesc->dmelem[nAuraStatValue + -1];
          if ((byElemType != 0) && (byElemType < 0xd)) {
            nCalcResult = D2Client::UI::SkillDesc::SKILLDESC_ElemTypeToColorIndex((uint)byElemType);
            *pdwElemColorOut = nCalcResult;
          }
        }
      }
      nStateIdx = nStateIdx + 1;
    } while (nStateIdx < (short)D2Common::ITEMS::Items::sgptDataTable->nAllStatesDataTblFlag0x04Size
            );
  }
  return 1;
}
